,p_plug_name=>'Genesis Control Center'
,p_static_id=>'genesis-laboratory'
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>4502917002193490937
,p_plug_display_sequence=>10
,p_plug_grid_column_span=>12
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<div id="genesis-control">',
'<p class="eyebrow">ORACLE-OWNED STATE / AUTHENTICATED CONTROL</p><h1>Genesis Control Center</h1>',
'<p class="lede">The database owns every generation. Pending candidates await the browser evaluation worker.</p>',
'<label for="control-run">Experiment</label><select id="control-run"></select><section id="control-metrics" class="instrument-bar"></section>',
'<div class="transport"><button type="button" data-control="PAUSE">Pause</button><button type="button" data-control="RESUME">Resume</button><button type="button" data-control="STOP">Stop</button><button type="button" data-control="STEP">Run one genera'
||'tion</button><button type="button" data-control="STOP_AI">Stop AI</button></div>',
'<div class="configuration-grid"><label>Generation count<input id="run-count" type="number" min="1" max="100" value="5"></label><button type="button" data-control="RUN_N">Run N generations, then pause</button>',
'<label>Completed checkpoint generation<input id="checkpoint-generation" type="number" min="0" max="1000" value="0"></label><button type="button" data-control="CHECKPOINT">Duplicate checkpoint</button><button type="button" data-control="EXPORT">Downlo'
||'ad completed run JSON</button></div>',
'<p>Bounded requests include the current unfinished generation. A completed checkpoint is copied into a new run; its source history stays intact. The public publication pipeline separately produces the verified partitioned export.</p>',
'<p id="control-heartbeat" role="status"></p><h2>Evolution events</h2><ol id="control-events"></ol></div>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(7811287781526837)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'GENESIS_DATA'
,p_static_id=>'genesis-data'
,p_process_sql_clob=>'apxgen_web.ajax;'
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>7811287781526837
);
end;
