'<a class="skip" href="#laboratory">Skip to laboratory</a>',
unistr('<header class="masthead"><a class="wordmark" href="https://github.com/B2DEV-TECH/apex-genesis" target="_blank" rel="noopener"><span class="genesis-mark" aria-hidden="true">\2733</span><span>APEX <b>GENESIS</b><small>B2DEV TECH / EVOLUTION SYSTEMS</small>')
