'<div id="laboratory">',
unistr('<section class="intro"><div><p class="eyebrow">EVOLUTION EXPERIMENT <span>/</span> ORACLE \00D7 EVOLUTIONARY COMPUTATION</p><h1>Interfaces are born.<br><span>The database decides<br class="mobile-break"> who survives.</span></h1><p class="lede">A living ')
||'archive of selection, mutation and inheritance.<br>Every interface is a genome. Every generation leaves evidence.</p></div><div class="specimen-seal" aria-hidden="true"><div class="seal-orbit orbit-a"></div><div class="seal-orbit orbit-b"></div><div '
||unistr('class="seal-core">G<sub>0 \2192 100</sub></div><span>PL/SQL \00B7 SEEDED EVOLUTION</span></div></section>'),
unistr('<div id="load-status" role="status" class="load-status">Verifying the recorded experiment\2026</div>'),
'<div id="lab-content" hidden>',
unistr('<section class="instrument-bar" aria-label="Recorded experiment metrics"><div><span>ENGINE</span><strong>Oracle PL/SQL</strong></div><div><span>HISTORY</span><strong id="generation-count">\2014</strong></div><div><span>CANDIDATE RECORDS</span><strong id=')
||unistr('"candidate-count">\2014</strong></div><div><span>VIEWPORTS / CANDIDATE</span><strong>390 \00B7 768 \00B7 1440</strong></div><div><span>AI EVIDENCE</span><strong id="ai-evidence">\2014</strong></div></section>'),
'<nav class="lab-tabs" aria-label="Laboratory views"><button type="button" data-view="arena" aria-pressed="true">01 / Evolution Arena</button><button type="button" data-view="tree" aria-pressed="false">02 / Family Tree</button><button type="button" da'
||'ta-view="mutation" aria-pressed="false">03 / Mutation Microscope</button><button type="button" data-view="analytics" aria-pressed="false">04 / Research Analytics</button></nav>',
unistr('<section class="time-machine" aria-label="Evolution Time Machine"><div class="transport"><button type="button" id="play" class="primary" aria-label="Play recorded evolution">\25B6 Play</button><button type="button" id="back" aria-label="Previous generati')
||unistr('on">\2190</button><button type="button" id="next" aria-label="Next generation">\2192</button><label class="speed">Speed <select id="speed"><option value="1">1\00D7</option><option value="2">2\00D7</option><option value="4">4\00D7</option><option value=".5">0.5\00D7</option>')
||unistr('</select></label></div><div class="timeline-wrap"><div class="timeline-label"><label for="timeline">GENERATION <strong id="generation-label">000</strong></label><span id="timeline-end">0 \2192 100</span></div><input id="timeline" type="range" min="0" max')
||'="100" value="0" step="1" aria-label="Recorded generation"><div class="timeline-ticks"><span>ORIGIN</span><span>SELECTION</span><span>INHERITANCE</span><span>RECORDED END</span></div></div><button type="button" id="origin">Compare with origin</button'
||'></section>',
'<section id="arena-view" class="view"><div class="section-heading"><div><p class="eyebrow">THE EVOLUTION ARENA</p><h2>Explore recorded populations.</h2></div><p id="comparison-note">Both populations use the same seed and evaluation rules.</p></div><d'
||'iv class="tree-tools"><label>Left population <select id="left-population"></select></label><label>Right population <select id="right-population"></select></label></div><div class="arena-grid" id="arena-cards"></div><div class="race-panel"><div class='
||'"chart-heading"><h3>Fitness race</h3><span id="race-legend">BEST OF GENERATION <i class="legend-a"></i> DARWIN <i class="legend-b"></i> CONTROL</span></div><div id="race-chart"></div><p class="chart-note">Technical fitness is a declared proxy. It doe'
||'s not establish beauty or real-world usability. Regressions remain visible.</p></div></section>',
'<section id="tree-view" class="view" hidden><div class="section-heading"><div><p class="eyebrow">INHERITANCE / SELECTION / EXTINCTION</p><h2>Every organism has a history.</h2></div><div class="tree-tools"><label>Population <select id="tree-population'
||'"></select></label><label>Find organism ID<input id="tree-search" type="search" placeholder="For example: 1479" maxlength="20"></label><button type="button" id="tree-find">Find in population</button><label>Highlight method<select id="tree-method"><op'
||'tion value="">All methods</option><option>ELITE</option><option>CROSSOVER</option><option>MUTATION</option><option>AI</option><option>RANDOM</option><option>IMMIGRANT</option></select></label><button type="button" id="zoom-in" aria-label="Zoom in fam'
||unistr('ily tree">+</button><button type="button" id="zoom-out" aria-label="Zoom out family tree">\2212</button></div></div><p id="tree-search-status" role="status"></p><p id="tree-window" class="chart-note"></p><div id="tree-scroll" tabindex="0" aria-label="Scr')
||'ollable ancestry graph"><svg id="tree-svg" role="img" aria-label="Organism ancestry"></svg></div><p class="chart-note">Inspect a node to open its organism. The graph loads a local three-generation window; scroll to pan and use the controls to zoom.</'
||'p><div id="tree-inspector" class="inspector"></div></section>',
unistr('<section id="mutation-view" class="view" hidden><div class="section-heading"><div><p class="eyebrow">GENOTYPE \2192 PHENOTYPE</p><h2>Look inside a mutation.</h2></div><label>Organism <select id="mutation-organism"></select></label></div><div id="mutation')
||'-detail"></div></section>',
'<section id="analytics-view" class="view" hidden><div class="section-heading"><div><p class="eyebrow">OBSERVATIONS / LIMITS / REPRODUCTION</p><h2>What the measurements say.</h2></div></div><div id="analytics"></div></section>',
unistr('<section class="research-note"><span class="note-symbol" aria-hidden="true">\2197</span><div><h2>Open the experiment.</h2><p>This is recorded playback of database-owned evolution. Download the configuration, genomes, lineage and measured observations, or')
||unistr(' reproduce a run in your own Oracle laboratory.</p><a href="https://github.com/B2DEV-TECH/apex-genesis">Explore the source & evidence \2197</a> <a id="manifest-link" href="./datasets/haiku-paired/manifest.json">Integrity manifest \2197</a></div></section>'),
'</div>',
unistr('</div><footer><span>APEX GENESIS / B2DEV TECH</span><span>Independent open-source research \00B7 Geraldo Viana Jr. \00B7 Apache-2.0</span></footer>'),
unistr('<dialog id="organism-dialog"><div class="dialog-top"><h2 id="dialog-title">Organism</h2><button type="button" id="close-dialog" aria-label="Close organism inspector">\2715</button></div><div class="viewport-controls"><button type="button" data-width="144')
||'0">Desktop</button><button type="button" data-width="768">Tablet</button><button type="button" data-width="390">Mobile</button></div><div class="dialog-preview"><iframe id="dialog-frame" title="Full-size organism" sandbox="allow-scripts"></iframe></d'
||'iv><pre id="dialog-metrics"></pre></dialog>',
'</div>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
